_BOOK = None


def mirror_bitboard(position):
    mirrored = 0

    column_mask = (1 << 7) - 1

    for col in range(7):
        column = (
            position >> (col * 7)
        ) & column_mask

        mirrored |= (
            column << ((6 - col) * 7)
        )

    return mirrored


def mirror_move(col):
    return 6 - col


def mirror_move_mask(mask):
    mirrored = 0

    for col in range(7):
        if mask & (1 << col):
            mirrored |= (
                1 << mirror_move(col)
            )

    return mirrored


def load_opening_book():
    global _BOOK

    if _BOOK is not None:
        return _BOOK

    compressed = base64.b85decode(
        BOOK_DATA_B85.encode("ascii")
    )

    raw = lzma.decompress(
        compressed
    )

    book = {}

    size = BOOK_RECORD.size

    if len(raw) % size != 0:
        raise ValueError(
            "Corrupt embedded opening book"
        )

    for offset in range(
        0,
        len(raw),
        size,
    ):
        p1, p2, score, move_mask = (
            BOOK_RECORD.unpack_from(
                raw,
                offset,
            )
        )

        book[(p1, p2)] = (
            score,
            move_mask,
        )

    _BOOK = book

    return _BOOK


def book_lookup(p1, p2):
    book = load_opening_book()

    result = book.get(
        (p1, p2)
    )

    if result is not None:
        return result

    mp1 = mirror_bitboard(p1)
    mp2 = mirror_bitboard(p2)

    result = book.get(
        (mp1, mp2)
    )

    if result is None:
        return None

    score, move_mask = result

    return (
        score,
        mirror_move_mask(move_mask),
    )


def book_best_moves(p1, p2):
    result = book_lookup(
        p1,
        p2,
    )

    if result is None:
        return None

    _, move_mask = result

    return [
        col
        for col in range(7)
        if move_mask & (1 << col)
    ]


def book_choose_move(p1, p2):
    result = book_lookup(
        p1,
        p2,
    )

    if result is None:
        return None

    _, move_mask = result

    for col in CENTER_ORDER:
        if move_mask & (1 << col):
            return col

    return None


# ============================================================
# KAGGLE AGENT
# ============================================================

def agent(observation, configuration):
    p1, p2 = board_to_bitboards(
        observation.board
    )

    player = observation.mark

    # Solved opening theory first.
    book_move = book_choose_move(
        p1,
        p2,
    )

    if book_move is not None:
        return int(book_move)

    # Search after leaving the book.
    engine = SearchEngine(
        time_limit=1.65
    )

    move = engine.choose_move(
        p1,
        p2,
        player,
    )

    return int(move)
